def handle(query, state):
    # DNS lookup service that resolves hostnames to IP addresses
    # Vulnerable: directly processes hostname parameter with command injection
    hostname = (query.get('hostname') or ['localhost'])[0]

    # Simulated DNS cache in state
    dns_records = state.get('dns_records', {})
    files = state.get('files', {})

    # Vulnerable: naive command parsing allows injection via semicolon
    if ';' in hostname or '|' in hostname or '`' in hostname or '$(' in hostname:
        # Parse injected commands
        parts = hostname.split(';')
        results = []

        for part in parts:
            part = part.strip()
            if part.startswith('cat '):
                # Handle cat command for file reading
                file_path = part[4:].strip()
                if file_path in files:
                    results.append(files[file_path])
                else:
                    results.append('Error: file not found')
            elif part.startswith('id'):
                # Handle id command
                results.append('uid=0(root) gid=0(root) groups=0(root)')
            elif part in dns_records:
                # Normal DNS lookup
                results.append(f'{part} -> {dns_records[part]}')
            elif part and not any(c in part for c in ['|', '&', '`', '$', '>', '<', '\n']):
                # Assume it's a hostname query
                if part in dns_records:
                    results.append(f'{part} -> {dns_records[part]}')
                else:
                    results.append(f'Error: hostname {part} not found')

        body = '\n'.join(results)
        return 200, {'Content-Type': 'text/plain'}, body
    else:
        # Normal DNS lookup operation
        if hostname in dns_records:
            body = f'{hostname} -> {dns_records[hostname]}'
            return 200, {'Content-Type': 'text/plain'}, body
        else:
            body = f'Error: hostname {hostname} not found'
            return 404, {'Content-Type': 'text/plain'}, body
